'use client'

import { useState, useEffect } from 'react'

export function OfflineIndicator() {
  const [isOnline, setIsOnline] = useState(true)

  useEffect(() => {
    function updateOnlineStatus() {
      setIsOnline(navigator.onLine)
    }

    window.addEventListener('online', updateOnlineStatus)
    window.addEventListener('offline', updateOnlineStatus)

    return () => {
      window.removeEventListener('online', updateOnlineStatus)
      window.removeEventListener('offline', updateOnlineStatus)
    }
  }, [])

  if (isOnline) return null

  return (
    <div className="fixed bottom-4 left-4 rounded-lg bg-yellow-100 px-4 py-2 text-yellow-800">
      You are offline. Changes will sync when you reconnect.
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'

interface QueuedAction {
  id: string
  url: string
  method: string
  body: unknown
}

function useOfflineQueue() {
  const [queue, setQueue] = useState<QueuedAction[]>([])

  useEffect(() => {
    async function flushQueue() {
      if (!navigator.onLine) return

      const pending = queue.filter((action) => !action.sent)
      for (const action of pending) {
        try {
          await fetch(action.url, {
            method: action.method,
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(action.body)
          })
          setQueue((prev) =>
            prev.map((a) =>
              a.id === action.id ? { ...a, sent: true } : a
            )
          )
        } catch {
          break // stop flushing if network fails again
        }
      }
    }

    window.addEventListener('online', flushQueue)
    return () => window.removeEventListener('online', flushQueue)
  }, [queue])

  function enqueue(action: QueuedAction) {
    setQueue((prev) => [...prev, action])
    localStorage.setItem('offlineQueue', JSON.stringify([...queue, action]))
  }

  return { queue, enqueue }
}
